def transform(grid):
    """Compare aligned cells across a solid divider; equal becomes 3."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            upper, lower = grid[:r], grid[r + 1:]
            common = {v for line in upper for v in line} & {v for line in lower for v in line}
            bg = Counter(v for line in lower for v in line if v in common).most_common(1)[0][0]
            return [[3 if a == b else bg for a, b in zip(ra, rb)]
                    for ra, rb in zip(upper, lower)]
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            common = {v for row in left for v in row} & {v for row in right for v in row}
            bg = Counter(v for row in right for v in row if v in common).most_common(1)[0][0]
            return [[3 if a == b else bg for a, b in zip(ra, rb)]
                    for ra, rb in zip(left, right)]
    raise ValueError('No solid divider found')
